async function publishFile(ev){ev.preventDefault();let f=$('#publishFile').files[0];if(!f)return;let ids=[...document.querySelectorAll('.publishPlan:checked')].map(x=>Number(x.value));if(!ids.length)return toast('اشتراک مقصد را انتخاب کن.');let rates={};document.querySelectorAll('.rateInput').forEach(x=>rates[x.dataset.product]=Number(x.value||0));if(f.size>30*1024*1024)return toast('حداکثر حجم فایل ۳۰ مگابایت است.');let rd=new FileReader();rd.onload=async()=>{try{let r=await api('/admin/publish-file','POST',{filename:$('#publishName').value||f.name,file_data:rd.result,product_ids:ids,rates,difficulty:$('#publishDifficulty').value,description:$('#publishDescription').value});toast(`تحلیل: ${r.analysis.difficulty} · انتشار برای ${fa(r.assigned)} مشتری؛ کمبود توکن ${fa(r.skipped)}؛ قبلاً دریافت کرده ${fa(r.already||0)}`);await render('files')}catch(e){toast(e.message)}};rd.readAsDataURL(f)}
async function openCustomerFile(id){try{let f=await api('/customer/file-view?id='+id);if(f.type==='PDF'){await openPdfReader('files',id,f.name);return}let body=`<div class="reader-toolbar"><span>محتوای تعاملی در محیط ایزوله اجرا می‌شود.</span><button class="tiny" onclick="readerZoom('htmlReaderFrame',-0.1)">−</button><button class="tiny" onclick="readerZoom('htmlReaderFrame',0.1)">+</button><button class="tiny" onclick="readerZoom('htmlReaderFrame',0,true)">اندازه اصلی</button><button class="tiny" onclick="readerFullscreen('htmlReaderFrame')">تمام‌صفحه</button></div><iframe id="htmlReaderFrame" class="html-runner" allowfullscreen sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer" src="${f.url}"></iframe>`;openModal(f.name,body)}catch(e){toast(e.message)}}
let pdfReaderState=null,pdfjsPromise=null;
async function getPdfJs(){if(!pdfjsPromise)pdfjsPromise=(async()=>{let lib;try{lib=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs'}catch{lib=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs'}return lib})();return pdfjsPromise}
async function openPdfReader(source,id,name){try{let lib=await getPdfJs();let loading=lib.getDocument({url:`/api/pdf-file?source=${encodeURIComponent(source)}&id=${id}`,httpHeaders:{'X-Vexta-Session':token},withCredentials:false,disableAutoFetch:true,disableStream:true,rangeChunkSize:65536});let doc=await loading.promise;pdfReaderState={source,id,doc,loading,page:1,zoom:1,renderTask:null,matches:[],generation:0};let body=`<div class="reader-toolbar pdf-reader-toolbar"><button class="tiny" onclick="pdfPrev()">قبلی</button><label class="pdf-page-label">صفحه <input id="pdfPageNumber" type="number" min="1" max="${doc.numPages}" value="1" onchange="pdfGoToPage(this.value)"></label><span>از <b id="pdfPageCount">${fa(doc.numPages)}</b></span><button class="tiny" onclick="pdfNext()">بعدی</button><button class="tiny" onclick="pdfZoom(-0.15)">−</button><span id="pdfZoomLabel">۱۰۰٪</span><button class="tiny" onclick="pdfZoom(0.15)">+</button><button class="tiny" onclick="readerFullscreen('pdfReaderViewport')">تمام‌صفحه</button></div><div class="pdf-searchbar"><input id="pdfSearchInput" placeholder="جستجو در متن PDF…" onkeydown="if(event.key==='Enter')pdfSearch()"><button class="tiny" onclick="pdfSearch()">جستجو</button><span id="pdfSearchStatus" class="muted"></span></div><div id="pdfSearchResults" class="pdf-search-results"></div><div id="pdfReaderViewport" class="pdf-reader-viewport"><div id="pdfReaderPage" class="pdf-reader-page"><div class="empty">در حال آماده‌سازی صفحه…</div></div></div><p class="muted pdf-reader-note">نمایش PDF در مرورگر انجام می‌شود؛ دانلود و چاپ در ابزارهای نمایشگر ارائه نشده است.</p>`;openModal(name,body);await pdfLoadPage(1)}catch(e){toast('باز کردن PDF ناموفق بود: '+e.message)}}
async function pdfLoadPage(page){let s=pdfReaderState;if(!s)return;page=Math.max(1,Math.min(s.doc.numPages,Number(page)||1));s.page=page;let gen=++s.generation,wrap=$('#pdfReaderPage');if(!wrap)return;if(s.renderTask){try{s.renderTask.cancel()}catch{}}wrap.innerHTML='<div class="empty">در حال بارگذاری صفحه…</div>';$('#pdfPageNumber').value=page;try{let pg=await s.doc.getPage(page);if(pdfReaderState!==s||gen!==s.generation)return;let box=$('#pdfReaderViewport'),base=pg.getViewport({scale:1});let fit=Math.min(1.5,Math.max(.35,(box.clientWidth-28)/base.width)),viewport=pg.getViewport({scale:fit*s.zoom}),outputScale=Math.min(window.devicePixelRatio||1,1.5);let canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{alpha:false});canvas.width=Math.floor(viewport.width*outputScale);canvas.height=Math.floor(viewport.height*outputScale);canvas.style.width=Math.floor(viewport.width)+'px';canvas.style.height=Math.floor(viewport.height)+'px';canvas.className='pdf-canvas';let pageBox=document.createElement('div');pageBox.className='pdf-page';pageBox.style.width=Math.floor(viewport.width)+'px';pageBox.style.height=Math.floor(viewport.height)+'px';pageBox.appendChild(canvas);let mark=document.createElement('div');mark.className='pdf-watermark';mark.textContent=role==='customer'?`${me.data.name||'مشتری'} · ${me.data.phone||''} · VEXTA`:'VEXTA ADMIN';pageBox.appendChild(mark);wrap.replaceChildren(pageBox);s.renderTask=pg.render({canvasContext:ctx,viewport,transform:outputScale!==1?[outputScale,0,0,outputScale,0,0]:null,background:'rgb(255,255,255)'});await s.renderTask.promise;if(pdfReaderState!==s||gen!==s.generation)return;$('#pdfZoomLabel').textContent=fa(Math.round(s.zoom*100))+'٪';box.scrollTop=0;pg.cleanup()}catch(e){if(e?.name!=='RenderingCancelledException'&&pdfReaderState===s&&gen===s.generation)wrap.innerHTML=`<div class="empty">${esc(e.message||'رندر صفحه ناموفق بود.')}</div>`}}
function pdfGoToPage(page){pdfLoadPage(page)}function pdfPrev(){if(pdfReaderState)pdfLoadPage(pdfReaderState.page-1)}function pdfNext(){if(pdfReaderState)pdfLoadPage(pdfReaderState.page+1)}function pdfZoom(delta){if(!pdfReaderState)return;pdfReaderState.zoom=Math.max(.65,Math.min(2.2,Math.round((pdfReaderState.zoom+delta)*100)/100));pdfLoadPage(pdfReaderState.page)}
async function pdfSearch(){let s=pdfReaderState,input=$('#pdfSearchInput');if(!s||!input)return;let q=input.value.trim();if(!q){$('#pdfSearchStatus').textContent='عبارت جستجو را وارد کن.';return}$('#pdfSearchStatus').textContent='جستجو روی دستگاه شما در حال انجام است…';s.matches=[];let needle=normalizePdfText(q);try{for(let n=1;n<=s.doc.numPages;n++){if(pdfReaderState!==s)return;let page=await s.doc.getPage(n),content=await page.getTextContent(),plain=content.items.map(x=>x.str||'').join(' '),norm=normalizePdfText(plain);if(norm.includes(needle)){let pos=norm.indexOf(needle);s.matches.push({page:n,snippet:plain.slice(Math.max(0,pos-45),Math.min(plain.length,pos+q.length+65))})}page.cleanup();if(n%6===0){$('#pdfSearchStatus').textContent=`بررسی ${fa(n)} از ${fa(s.doc.numPages)} صفحه…`;await new Promise(r=>setTimeout(r,0))}if(s.matches.length>=100)break}$('#pdfSearchStatus').textContent=`${fa(s.matches.length)} نتیجه پیدا شد` ;$('#pdfSearchResults').innerHTML=s.matches.slice(0,40).map(m=>`<button class="tiny" onclick="pdfGoToPage(${m.page})">صفحه ${fa(m.page)} · ${esc(m.snippet)}</button>`).join('');if(s.matches.length)await pdfLoadPage(s.matches[0].page)}catch(e){$('#pdfSearchStatus').textContent='جستجو ناموفق بود: '+e.message}}
function normalizePdfText(v){return String(v||'').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/ـ/g,'').toLocaleLowerCase()}
function cleanupPdfReader(){if(pdfReaderState){try{pdfReaderState.renderTask?.cancel()}catch{}try{pdfReaderState.loading?.destroy()}catch{}try{pdfReaderState.doc?.destroy()}catch{}}pdfReaderState=null}
function readerZoom(id,delta,reset=false){let el=document.getElementById(id);if(!el)return;let z=reset?1:Math.max(.5,Math.min(2,Number(el.dataset.zoom||1)+delta));el.dataset.zoom=String(z);el.style.zoom=String(z)}
async function readerFullscreen(id){let el=document.getElementById(id);if(!el)return;try{if(document.fullscreenElement)await document.exitFullscreen();else await el.requestFullscreen()}catch(e){toast('حالت تمام‌صفحه در این مرورگر پشتیبانی نمی‌شود.')}}
