function uploadReceipt(id){openModal('ارسال فیش پرداخت',`<p class="muted">تصویر یا PDF رسید پرداخت را انتخاب کن. فیش همراه نام و زمان ارسال برای مدیریت ثبت می‌شود.</p><input id="receiptFile" type="file" accept="image/*,application/pdf"><button class="btn primary full" onclick="sendReceipt(${id})">ارسال فیش</button>`)}
async function sendReceipt(id){let f=$('#receiptFile').files[0];if(!f)return toast('ابتدا فایل فیش را انتخاب کن.');if(f.size>8*1024*1024)return toast('حجم فایل باید کمتر از ۸ مگابایت باشد.');let rd=new FileReader();rd.onload=async()=>{try{await api('/customer/receipt','POST',{order_id:id,filename:f.name,file_data:rd.result});closeModal();toast('فیش برای بررسی ارسال شد.');await render('orders')}catch(e){toast(e.message)}};rd.readAsDataURL(f)}
function toggleWalletReceipt(){let isTopup=$('#walletType')?.value==='شارژ';let wrap=$('#walletReceiptWrap');if(wrap)wrap.classList.toggle('hidden',!isTopup)}
async function walletRequest(e){e.preventDefault();try{let file=$('#walletReceipt')?.files?.[0],payload={type:$('#walletType').value,amount:Number($('#walletAmount').value),note:$('#walletNote').value};if(file){if(file.size>8*1024*1024)return toast('حجم رسید باید کمتر از ۸ مگابایت باشد.');if(!file.type.startsWith('image/')&&file.type!=='application/pdf')return toast('فرمت رسید باید تصویر یا PDF باشد.');payload.receipt_filename=file.name;payload.receipt_file_data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('خواندن فایل رسید ناموفق بود.'));r.readAsDataURL(file)})}await api('/customer/wallet-request','POST',payload);toast('درخواست و رسید آن برای مدیریت ارسال شد.');await render('wallet')}catch(x){toast(x.message)}}
async function viewWalletReceipt(id){let list=cache.wallet||await loadAdmin('wallet'),r=list.find(x=>x.id===id);if(!r?.data?.receipt_file_data)return toast('برای این درخواست رسیدی ثبت نشده است.');let d=r.data;if(d.receipt_file_data.startsWith('data:application/pdf;')){await openPdfReader('wallet',id,'رسید درخواست '+(d.request_type||'کیف پول'));return}openModal('رسید درخواست '+(d.request_type||'کیف پول'),`<div class="receipt-meta"><b>${esc(d.customer)}</b><span>${money(d.amount)}</span><small>${esc(d.receipt_filename||'رسید پرداخت')} · ${fmt(d.created_at)}</small></div><img class="receipt-preview" src="${d.receipt_file_data}" alt="رسید پرداخت">`)}
async function review(entity,id,decision){let reason='';if(decision==='reject'){reason=prompt('دلیل رد درخواست را وارد کن:')||'';if(!reason.trim())return toast('برای رد درخواست، دلیل لازم است.')}try{await api(`/admin/review/${entity}/${id}`,'POST',{decision,reason});toast(decision==='approve'?'درخواست تأیید شد.':'درخواست رد شد.');await render(active)}catch(e){toast(e.message)}}
async function viewReceipt(id){let r=(cache.receipts||await loadAdmin('receipts')).find(x=>x.id===id);if(!r)return;let d=r.data;if(!d.file_data)return toast('فیش پس از تأیید از فضای ذخیره‌سازی حذف شده است.');if(d.file_data?.startsWith('data:application/pdf;')){await openPdfReader('receipts',id,'فیش سفارش '+(d.order_code||d.order_id));return}openModal('فیش پرداخت',`<div class="receipt-meta"><b>${esc(d.customer)}</b><span>${money(d.amount)}</span><small>${esc(d.order_code||'') } · ${fmt(d.sent_at)}</small></div><img class="receipt-preview" src="${d.file_data}" alt="فیش پرداخت">`)}
function openModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').classList.remove('hidden')}function closeModal(){cleanupPdfReader();$('#modal').classList.add('hidden')}
function openRecord(entity,id){let rec=id?(cache[entity]||[]).find(x=>x.id===id):null;let fs=fields[entity]||[];openModal(id?'ویرایش اطلاعات':'افزودن مورد جدید',`<form id="recordForm" class="record-form">${fs.map(f=>{let v=rec?.data?.[f[0]]??'';let el=f[2]==='textarea'?`<textarea name="${f[0]}">${esc(v)}</textarea>`:f[2]==='select'?`<select name="${f[0]}">${f[3].split('|').map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('')}</select>`:`<input name="${f[0]}" ${['number','date'].includes(f[2])?`type="${f[2]}"`:''} value="${esc(v)}">`;return `<label>${f[1]}${el}</label>`}).join('')}<button class="btn primary full">ذخیره</button></form>`);$('#recordForm').onsubmit=async e=>{e.preventDefault();let d={};new FormData(e.target).forEach((v,k)=>{let f=fs.find(x=>x[0]===k);d[k]=f?.[2]==='number'?Number(v):v});try{await api('/admin/data/'+entity+(id?'/'+id:''),id?'PUT':'POST',d);closeModal();toast('اطلاعات ذخیره شد.');await render(entity==='products'?'products':entity)}catch(x){toast(x.message)}}}
