function updateClock(){let d=new Date();$('#liveClock').textContent=d.toLocaleTimeString('fa-IR');$('#liveDate').textContent=d.toLocaleDateString('fa-IR',{weekday:'long',year:'numeric',month:'long',day:'numeric'});let dc=$('#dashClock');if(dc)dc.textContent=d.toLocaleTimeString('fa-IR')}
function themeKey(){return 'vextaTheme_'+(role==='admin'?'admin':role==='customer'?(me?.data?.phone||'customer'):'public')}function setTheme(v){localStorage.setItem(themeKey(),v);applyTheme()};function cycleTheme(){let v=localStorage.getItem(themeKey())||'auto';setTheme(v==='dark'?'light':v==='light'?'auto':'dark')};function applyTheme(){let v=localStorage.getItem(themeKey())||'auto';let dark=v==='dark'||(v==='auto'&&(new Date().getHours()<7||new Date().getHours()>=19));document.body.dataset.theme=dark?'dark':'light';let ic=dark?'fa-moon':'fa-sun';['themeIcon','appThemeIcon'].forEach(id=>{let el=document.getElementById(id);if(el)el.className='fa-solid '+ic})}

async function reviewDeviceChange(id,decision){let reason='';if(decision==='reject'){reason=prompt('دلیل رد درخواست را بنویس:')||'';if(!reason.trim())return toast('دلیل رد درخواست الزامی است.')}try{await api(`/admin/device-change/${decision}/${id}`,'POST',{reason});toast(decision==='approve'?'دستگاه قبلی آزاد شد؛ اتصال دستگاه جدید مجاز است.':'درخواست رد شد.');await render('devices')}catch(e){toast(e.message)}}
