async function deleteMyAccount(){if(!confirm('هشدار: کیف پول، توکن‌ها و اشتراک‌های فعال از بین می‌روند و قابل‌بازیابی نیستند. ادامه می‌دهی؟'))return;let phrase=prompt('برای تأیید نهایی عبارت حذف حساب را دقیقاً وارد کن: حذف حساب');if(phrase!=='حذف حساب')return toast('عبارت تأیید صحیح نبود.');try{await api('/customer/delete-account','POST',{confirm:true,confirmation_phrase:phrase});sessionStorage.removeItem('vextaToken');token='';role='';me=null;showHome();toast('حساب حذف شد. سوابق مالی لازم حفظ شده‌اند.')}catch(e){toast(e.message)}}
