function restore(){let saved=sessionStorage.getItem('vextaToken');if(saved){token=saved;api('/me').then(s=>{role=s.role;me=s.role==='customer'?{data:s.customer_data||{name:s.name,phone:s.phone||''}}:{data:{name:s.name}};if(role==='customer')api('/customer/data').then(()=>startApp());else startApp()}).catch(()=>{sessionStorage.removeItem('vextaToken');showHome()})}}
applyTheme();setInterval(()=>{applyTheme();updateClock()},1000);setInterval(()=>{if(role)updateNotifCount()},30000);restore();
